from __future__ import annotations

import subprocess
import os
import getpass
import shutil
from dataclasses import dataclass
from typing import Any, AsyncIterator

from apex_backend.host_control import HostControlClient, HostControlError


@dataclass(frozen=True)
class ModuleConfig:
    module_id: str
    display_name: str
    service: str
    description: str


MODULES: dict[str, ModuleConfig] = {
    "camera": ModuleConfig(
        module_id="camera",
        display_name="Camera",
        service="apex-camera.service",
        description="GMSL quad camera and WebRTC stream.",
    ),
    "robot": ModuleConfig(
        module_id="robot",
        display_name="Robot Control",
        service="apex-robot.service",
        description="Marvin ROS control and robot state publisher.",
    ),
    "teleop": ModuleConfig(
        module_id="teleop",
        display_name="Teleop + Replay",
        service="apex-teleop.service",
        description="Teleoperation, IK, planner, command mux and replay nodes.",
    ),
    "dnsmasq": ModuleConfig(
        module_id="dnsmasq",
        display_name="DNSMasq DHCP",
        service="apex-dnsmasq.service",
        description="DHCP service for automatic robot-side IP assignment.",
    ),
    "tool": ModuleConfig(
        module_id="tool",
        display_name="Tool",
        service="apex-tool.service",
        description="End-effector tool module for DM gripper, ZY gripper, or Wuji hands.",
    ),
}


class ServiceManagerError(RuntimeError):
    def __init__(self, message: str, returncode: int | None = None):
        super().__init__(message)
        self.returncode = returncode


class ServiceManager:
    STATUS_PROPERTIES = (
        "Id",
        "LoadState",
        "ActiveState",
        "SubState",
        "UnitFileState",
        "Result",
        "ExecMainPID",
        "ExecMainStatus",
        "FragmentPath",
        "ActiveEnterTimestamp",
        "InactiveEnterTimestamp",
        "StateChangeTimestamp",
    )

    def __init__(self, modules: dict[str, ModuleConfig] | None = None) -> None:
        self.modules = modules or MODULES
        socket_path = os.environ.get("APEX_HOST_CONTROL_SOCKET", "").strip()
        self._host_control = HostControlClient(socket_path) if socket_path else None

    @property
    def host_control_enabled(self) -> bool:
        return self._host_control is not None

    def list_modules(self) -> list[dict[str, Any]]:
        return [self.get_status(module_id) for module_id in self.modules]

    def get_config(self, module_id: str) -> ModuleConfig:
        try:
            return self.modules[module_id]
        except KeyError as exc:
            raise KeyError(f"Unknown module '{module_id}'") from exc

    def get_status(self, module_id: str) -> dict[str, Any]:
        config = self.get_config(module_id)
        props = self._show(config.service)
        active_state = props.get("ActiveState", "unknown")
        load_state = props.get("LoadState", "unknown")
        result = props.get("Result", "")
        exec_status = props.get("ExecMainStatus", "")
        failed = active_state == "failed" or result not in ("", "success")
        return {
            "id": config.module_id,
            "name": config.display_name,
            "description": config.description,
            "service": config.service,
            "load_state": load_state,
            "unit_file_state": props.get("UnitFileState", "unknown"),
            "active_state": active_state,
            "sub_state": props.get("SubState", "unknown"),
            "result": result,
            "exec_main_pid": _to_int(props.get("ExecMainPID")),
            "exec_main_status": _to_int(exec_status),
            "fragment_path": props.get("FragmentPath", ""),
            "active_enter_timestamp": props.get("ActiveEnterTimestamp", ""),
            "inactive_enter_timestamp": props.get("InactiveEnterTimestamp", ""),
            "state_change_timestamp": props.get("StateChangeTimestamp", ""),
            "healthy": load_state == "loaded" and active_state == "active" and not failed,
            "error": failed,
        }

    def start(self, module_id: str) -> dict[str, Any]:
        config = self.get_config(module_id)
        self._systemctl(["start", config.service], timeout=45)
        return self.get_status(module_id)

    def stop(self, module_id: str) -> dict[str, Any]:
        config = self.get_config(module_id)
        self._systemctl(["stop", config.service], timeout=45)
        return self.get_status(module_id)

    def restart(self, module_id: str) -> dict[str, Any]:
        config = self.get_config(module_id)
        self._systemctl(["restart", config.service], timeout=60)
        return self.get_status(module_id)

    def get_logs(self, module_id: str, lines: int = 200) -> dict[str, Any]:
        config = self.get_config(module_id)
        safe_lines = max(1, min(lines, 2000))
        if self._host_control is not None:
            try:
                result = self._host_control.journal(config.service, safe_lines)
            except HostControlError as exc:
                raise ServiceManagerError(str(exc)) from exc
            return {
                "module": module_id,
                "service": config.service,
                "lines": safe_lines,
                "logs": str(result.get("stdout", "")).splitlines(),
            }
        result = self._run(
            self._journalctl_args(
                [
                    "-u",
                    config.service,
                    "-n",
                    str(safe_lines),
                    "--no-pager",
                    "-o",
                    "short-iso",
                ]
            ),
            timeout=20,
        )
        return {
            "module": module_id,
            "service": config.service,
            "lines": safe_lines,
            "logs": result.stdout.splitlines(),
        }

    def get_system_errors(self, lines: int = 100) -> dict[str, Any]:
        safe_lines = max(1, min(lines, 1000))
        permissions = self.get_permissions()
        if self._host_control is not None:
            try:
                result = self._host_control.journal(
                    None, safe_lines, priority="err..alert"
                )
                errors = str(result.get("stdout", "")).splitlines()
            except HostControlError as exc:
                errors = [str(exc)]
            if not permissions["ready"]:
                errors.append(permissions["message"])
            return {"lines": safe_lines, "errors": errors, "permissions": permissions}
        args = self._journalctl_args(["-p", "err..alert", "-n", str(safe_lines), "--no-pager", "-o", "short-iso"])
        result = self._run(args, timeout=20, check=False)
        errors = result.stdout.splitlines()
        if result.returncode != 0:
            message = _permission_error_message(args, result) or result.stderr.strip() or result.stdout.strip()
            if message:
                errors.append(message)
        if not permissions["ready"]:
            errors.append(permissions["message"])
        return {"lines": safe_lines, "errors": errors, "permissions": permissions}

    def get_permissions(self) -> dict[str, Any]:
        if self._host_control is not None:
            try:
                result = self._host_control.permissions()
                checks = []
                for config in self.modules.values():
                    for action in ("start", "stop", "restart"):
                        checks.append(
                            {
                                "label": f"systemctl {action} {config.service}",
                                "command": ["/usr/bin/systemctl", action, config.service],
                                "allowed": True,
                                "returncode": 0,
                                "error": "",
                            }
                        )
                checks.append(
                    {
                        "label": "journalctl module logs",
                        "command": [
                            "/usr/bin/journalctl",
                            "-u",
                            MODULES["robot"].service,
                            "-n",
                            "1",
                            "--no-pager",
                        ],
                        "allowed": True,
                        "returncode": 0,
                        "error": "",
                    }
                )
                return {
                    "user": getpass.getuser(),
                    "euid": os.geteuid(),
                    "root": os.geteuid() == 0,
                    "ready": bool(result.get("ready", False)),
                    "mode": result.get("mode", "host-control-socket"),
                    "socket": result.get("socket", ""),
                    "checks": checks,
                    "message": "Apex backend host control permissions are ready.",
                }
            except HostControlError as exc:
                return {
                    "user": getpass.getuser(),
                    "euid": os.geteuid(),
                    "root": os.geteuid() == 0,
                    "ready": False,
                    "mode": "host-control-socket",
                    "socket": self._host_control.socket_path,
                    "checks": [],
                    "message": str(exc),
                }
        systemctl_path = shutil.which("systemctl") or "/usr/bin/systemctl"
        journalctl_path = shutil.which("journalctl") or "/usr/bin/journalctl"
        is_root = os.geteuid() == 0
        checks: list[dict[str, Any]] = []

        for config in self.modules.values():
            for action in ("start", "stop", "restart"):
                command = [systemctl_path, action, config.service]
                checks.append(self._sudo_permission_check(f"systemctl {action} {config.service}", command, is_root))

        journal_command = [journalctl_path, "-u", MODULES["robot"].service, "-n", "1", "--no-pager"]
        checks.append(self._sudo_permission_check("journalctl module logs", journal_command, is_root))

        missing = [check for check in checks if not check["allowed"]]
        return {
            "user": getpass.getuser(),
            "euid": os.geteuid(),
            "root": is_root,
            "ready": not missing,
            "checks": checks,
            "message": (
                "Apex backend sudo permissions are ready."
                if not missing
                else "Apex backend sudo permissions are missing. Run install_systemd_services.sh from a terminal."
            ),
        }

    def _show(self, service: str) -> dict[str, str]:
        args = ["show", service]
        for prop in self.STATUS_PROPERTIES:
            args.extend(["--property", prop])
        result = self._systemctl(args, timeout=15, check=False)
        if result.returncode != 0:
            return {
                "Id": service,
                "LoadState": "not-found",
                "ActiveState": "unknown",
                "SubState": "unknown",
                "Result": "systemctl-show-failed",
                "ExecMainStatus": str(result.returncode),
            }
        props: dict[str, str] = {}
        for line in result.stdout.splitlines():
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            props[key] = value
        return props

    def _systemctl(
        self,
        args: list[str],
        timeout: int,
        check: bool = True,
    ) -> subprocess.CompletedProcess[str]:
        if self._host_control is not None:
            if not args or args[0] not in {"show", "start", "stop", "restart"}:
                raise ServiceManagerError("Unsupported host systemctl request")
            action = args[0]
            if len(args) < 2:
                raise ServiceManagerError("Host systemctl request is missing a service")
            service = args[1]
            properties: list[str] = []
            index = 2
            while index < len(args):
                if args[index] != "--property" or index + 1 >= len(args):
                    raise ServiceManagerError("Unsupported host systemctl arguments")
                properties.append(args[index + 1])
                index += 2
            try:
                result = self._host_control.systemctl(
                    action, service, properties=properties, timeout=timeout
                )
            except HostControlError as exc:
                if check:
                    raise ServiceManagerError(str(exc)) from exc
                return subprocess.CompletedProcess(args, 1, "", str(exc))
            completed = subprocess.CompletedProcess(
                args,
                int(result.get("returncode", 0)),
                str(result.get("stdout", "")),
                str(result.get("stderr", "")),
            )
            if check and completed.returncode != 0:
                raise ServiceManagerError(
                    completed.stderr.strip()
                    or completed.stdout.strip()
                    or "systemctl command failed",
                    completed.returncode,
                )
            return completed
        command = ["systemctl", *args]
        if os.geteuid() != 0 and args and args[0] in {"start", "stop", "restart"}:
            command = ["sudo", "-n", *command]
        return self._run(command, timeout=timeout, check=check)

    async def follow_logs(self, module_id: str, lines: int = 50) -> AsyncIterator[str]:
        config = self.get_config(module_id)
        if self._host_control is None:
            raise ServiceManagerError("Host control socket mode is not enabled")
        try:
            async for line in self._host_control.follow_journal(config.service, lines):
                yield line
        except HostControlError as exc:
            raise ServiceManagerError(str(exc)) from exc

    def _journalctl_args(self, args: list[str]) -> list[str]:
        command = ["journalctl", *args]
        if os.geteuid() != 0:
            command = ["sudo", "-n", *command]
        return command

    def _run(
        self,
        args: list[str],
        timeout: int,
        check: bool = True,
    ) -> subprocess.CompletedProcess[str]:
        try:
            result = subprocess.run(
                args,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise ServiceManagerError(f"Command timed out: {' '.join(args)}") from exc
        if check and result.returncode != 0:
            message = _permission_error_message(args, result) or result.stderr.strip() or result.stdout.strip() or "systemctl command failed"
            raise ServiceManagerError(message, result.returncode)
        return result

    def _sudo_permission_check(self, label: str, command: list[str], is_root: bool) -> dict[str, Any]:
        if is_root:
            return {"label": label, "command": command, "allowed": True, "returncode": 0, "error": ""}
        sudo_command = ["sudo", "-n", "-l", *command]
        result = subprocess.run(sudo_command, capture_output=True, text=True, timeout=10, check=False)
        return {
            "label": label,
            "command": command,
            "allowed": result.returncode == 0,
            "returncode": result.returncode,
            "error": (result.stderr or result.stdout).strip(),
        }


def _to_int(value: str | None) -> int | None:
    if not value:
        return None
    try:
        return int(value)
    except ValueError:
        return None


def _permission_error_message(args: list[str], result: subprocess.CompletedProcess[str]) -> str | None:
    if not args or args[0] != "sudo":
        return None
    output = f"{result.stderr}\n{result.stdout}".lower()
    permission_markers = (
        "a password is required",
        "interactive authentication required",
        "not in the sudoers file",
        "not allowed to execute",
        "may not run sudo",
    )
    if not any(marker in output for marker in permission_markers):
        return None
    return (
        "Apex backend sudo permission is not installed for this command. "
        "Run /opt/kernelmind/apex/install/apex_backend/share/apex_backend/scripts/"
        "install_systemd_services.sh from a terminal, then restart apex-backend.service."
    )
